// Apple release: composition rail helpers. Listening experiments removed from v1.
function ctHClone(value){return JSON.parse(JSON.stringify(value));}
function ctHPc(value){return (value%12+12)%12;}
function ctHNames(){return ['C','D♭','D','E♭','E','F','F♯','G','A♭','A','B♭','B'];}
function ctHState(){return window.ctHarmonyLab||(window.ctHarmonyLab={mode:'role',pattern:'1451',role:1,seed:0,extent:'auto',leading:false,undo:null});}
function ctHPatterns(){return [{id:'1451',label:'1–4–5–1',degrees:[1,4,5,1]},{id:'251',label:'2–5–1',degrees:[2,5,1]},{id:'51',label:'Authentic · 5–1',degrees:[5,1]},{id:'41',label:'Plagal · 4–1',degrees:[4,1]},{id:'56',label:'Deceptive · 5–6',degrees:[5,6]}];}
function ctHRoot(chord){return ctHPc(Number.isInteger(chord.chordRoot)?chord.chordRoot:chord.pcs[0]);}
function ctHMidis(chord){
 const notes=chord.midis?.length?[...chord.midis]:chord.pcs.map(pc=>48+ctHPc(pc-ctHRoot(chord))+ctHRoot(chord));
 const shift=Math.round((64-notes.reduce((s,n)=>s+n,0)/notes.length)/12)*12;
 return notes.map(n=>n+shift).sort((a,b)=>a-b);
}
function ctHLabel(root,pcs){
 const intervals=pcs.map(pc=>ctHPc(pc-root)),minor=intervals.includes(3),diminished=minor&&intervals.includes(6);
 let label=ctHNames()[root]+(diminished?'dim':minor?'m':intervals.includes(8)&&intervals.includes(4)?'aug':'');
 if(intervals.includes(11))label+=minor?'(maj7)':'maj7';else if(intervals.includes(10))label+='7';
 const colors=[[2,'9'],[5,'11'],[9,'13']].filter(([n])=>intervals.includes(n)).map(([,name])=>name);
 return label+(colors.length?' · '+colors.join('/'):'');
}
function ctHVoicing(pcs,reference){
 const sorted=[...new Set(pcs)].sort((a,b)=>a-b),ref=reference?.length?[...reference].sort((a,b)=>a-b):[55,60,64];
 let best=null;
 for(let inversion=0;inversion<sorted.length;inversion++)for(let octave=3;octave<=5;octave++){
  const notes=sorted.slice(inversion).concat(sorted.slice(0,inversion).map(n=>n+12)).map(n=>12*octave+n);
  if(notes[0]<43||notes.at(-1)>88)continue;
  const movement=notes.reduce((s,n,i)=>s+Math.abs(n-ref[Math.min(ref.length-1,Math.round(i*(ref.length-1)/Math.max(1,notes.length-1)))]),0)/notes.length;
  const score=movement+Math.abs(notes.reduce((a,b)=>a+b,0)/notes.length-64)*.3;
  if(!best||score<best.score)best={score,notes};
 }
 return ctHMidis({pcs,midis:best?.notes||sorted.map(pc=>60+pc),chordRoot:pcs[0]});
}
